using System;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using UnityEditor;using MashBoxSDK.AnimationStudio;
public static class StudioHandleFrameValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;public static int Checks;
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Checks++;}
 public static void Run(){int code=0;try{Validate();System.IO.File.WriteAllText(System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../handle-frame-validation.txt")),"PASS "+Checks+" cache/invalidation/Undo assertions");}catch(Exception e){code=1;System.IO.File.WriteAllText(System.IO.Path.GetFullPath(System.IO.Path.Combine(Application.dataPath,"../../handle-frame-validation.txt")),e.ToString());}EditorApplication.Exit(code);}
 public static void Validate(){var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);doc.nodes.Add(new StudioModelDocument.Node{name="Frame cache test",mesh=mesh,cutPolygons=polygons,cutTriangles=mesh.triangles});using(var ed=new StudioModelEditor(()=>{})){ed.Load(doc);ed.SelectObject(0);var type=typeof(StudioModelEditor);var frame=type.GetMethod("GetHandleComponentFrame",F);var center=type.GetMethod("ComponentSelectionCenter",F,null,new[]{typeof(IList<Vector3>),typeof(HashSet<int>)},null);
 object[] Read(){var args=new object[3];frame.Invoke(ed,args);return args;}
 void Reference(){var actual=Read();var selected=ed.SelectedVertices();var source=mesh.vertices;Check(((HashSet<int>)actual[0]).SetEquals(selected),"Resolved selection differs from reference");Check(((IList<Vector3>)actual[1]).SequenceEqual(source),"Source positions differ");Check(((Vector3)actual[2]-(Vector3)center.Invoke(ed,new object[]{source,selected})).sqrMagnitude<1e-12f,"Center differs");}
 type.GetField("mode",F).SetValue(ed,StudioModelEditor.ComponentMode.Vertex);ed.Components.Add(0);Reference();var before=Read();int builds=ed.HandleFrameBuilds;for(int i=0;i<20;i++){var next=Read();Check(ReferenceEquals(before[0],next[0])&&ReferenceEquals(before[1],next[1])&&ed.HandleFrameBuilds==builds,"Unchanged frame rebuilt");}
 ed.Components.Clear();ed.Components.Add(4);Reference();Check(ed.HandleFrameBuilds>builds,"Same-count selection change did not invalidate");type.GetField("weld",F).SetValue(ed,false);Reference();type.GetField("weld",F).SetValue(ed,true);Reference();
 ed.Transforms[0].position=new Vector3(2,3,4);ed.Transforms[0].rotation=Quaternion.Euler(21,35,8);ed.Transforms[0].localScale=new Vector3(2,-1,.7f);Reference();
 var p=mesh.vertices;p[4]+=Vector3.up*.2f;mesh.vertices=p;EditorUtility.SetDirty(mesh);Reference();
 foreach(var mode in new[]{StudioModelEditor.ComponentMode.Edge,StudioModelEditor.ComponentMode.Face,StudioModelEditor.ComponentMode.Vertex}){type.GetField("mode",F).SetValue(ed,mode);ed.Components.Clear();ed.Components.Add(0);Reference();}
 before=Read();type.GetMethod("RefreshComponentPositions",F).Invoke(ed,new object[]{0,null,null});Check(!ReferenceEquals(before[1],Read()[1]),"Position refresh did not invalidate before overlay capture");before=Read();type.GetMethod("ClearComponentDrawing",F).Invoke(ed,null);Check(!ReferenceEquals(before[1],Read()[1]),"Rebuild did not invalidate");
 ed.DisableHandleFrameCache=true;Reference();ed.DisableHandleFrameCache=false;Reference();
 var undoSource=mesh.vertices;StudioUndo.IncrementCurrentGroup();StudioUndo.RegisterCompleteObjectUndo(mesh,"Handle frame invalidation test");var edited=(Vector3[])undoSource.Clone();for(int i=0;i<edited.Length;i++)edited[i]+=Vector3.up*.1f;mesh.vertices=edited;EditorUtility.SetDirty(mesh);Reference();UnityEditor.Undo.FlushUndoRecordObjects();StudioUndo.PerformUndo();Check(mesh.vertices.SequenceEqual(undoSource),"Native Undo geometry differs");Reference();StudioUndo.PerformRedo();Check(mesh.vertices.SequenceEqual(edited),"Native Redo geometry differs");Reference();
 doc.nodes.Add(new StudioModelDocument.Node{name="Empty target"});ed.Load(doc);ed.SelectObject(1);type.GetField("mode",F).SetValue(ed,StudioModelEditor.ComponentMode.Vertex);var empty=Read();Check(((HashSet<int>)empty[0]).Count==0&&((IList<Vector3>)empty[1]).Count==0,"Nonmesh component target should have no handle selection");}UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(doc);}
}